export function latestMessages(messages, limit) {
  if (!Number.isInteger(limit) || limit < 0) {
    throw new RangeError('limit must be a non-negative integer');
  }
  if (messages.length === 0 || limit === 0) {
    return [];
  }
  return messages
    .map((message, index) => ({ message, index }))
    .sort((a, b) => b.message.timestamp - a.message.timestamp || a.index - b.index)
    .slice(0, limit)
    .map(({ message }) => message);
}
